import type { TabProps } from "./tab.types";

import React, { forwardRef, useRef } from "react";
import { useTheme } from "@theme";
import { clsx } from "clsx";

import { useTabBar } from "../../hooks/use-tab-bar";
import { TabActionButton } from "../tab-action-button";
import { TabBadge } from "../tab-badge";
import { TabInlineBadge } from "../tab-inline-badge";
import { TabIcon } from "../tab-icon";

import { StyledTab, TabClasses } from "./tab.styles";

const TabRoot = forwardRef<HTMLDivElement, TabProps>(
  ({ children, className, value, variant, size, styleSlots, style, onClick, ...props }, ref) => {
    const theme = useTheme();
    const context = useTabBar();
    const menuTriggerRef = useRef<HTMLButtonElement>(null);
    const actionButtonRef = useRef<HTMLButtonElement>(null);

    const resolvedVariant = variant ?? context?.variant;
    const resolvedSize = size ?? context?.size ?? "default";

    const tabClasses = clsx(TabClasses.root, resolvedSize === "sm" && TabClasses.sm, className);

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === "Enter" || e.key === " ") {
        if (menuTriggerRef.current) {
          e.preventDefault();
          menuTriggerRef.current.dispatchEvent(new MouseEvent("pointerdown", { bubbles: true }));
        } else if (actionButtonRef.current) {
          actionButtonRef.current.click();
        } else {
          (e.target as HTMLElement).click();
        }
      }
    };

    const findAndClone = (children: React.ReactNode): React.ReactNode => {
      return React.Children.map(children, (child) => {
        if (!React.isValidElement(child)) return child;

        if ((child.type as { displayName?: string }).displayName === "Menu.Trigger") {
          return React.cloneElement(child, { ref: menuTriggerRef });
        } else if ((child.type as { displayName?: string }).displayName === "Tab.ActionButton") {
          return React.cloneElement(child, { ref: actionButtonRef });
        }

        if (child.props.children) {
          return React.cloneElement(child, {
            children: findAndClone(child.props.children),
          });
        }

        return child;
      });
    };

    const childrenWithRef = findAndClone(children);

    return (
      <StyledTab
        asChild
        aria-disabled={props.disabled || undefined}
        className={tabClasses}
        currentTheme={theme}
        style={style}
        styleSlots={styleSlots}
        value={value ?? ""}
        variant={resolvedVariant}
        onClick={onClick}
        onKeyDown={handleKeyDown}
        {...props}
      >
        <div ref={ref}>{childrenWithRef}</div>
      </StyledTab>
    );
  },
);
TabRoot.displayName = "Tab";

const Tab = TabRoot as typeof TabRoot & {
  ActionButton: typeof TabActionButton;
  Badge: typeof TabBadge;
  InlineBadge: typeof TabInlineBadge;
  Icon: typeof TabIcon;
};

Tab.ActionButton = TabActionButton;
Tab.Badge = TabBadge;
Tab.InlineBadge = TabInlineBadge;
Tab.Icon = TabIcon;

export default Tab;
